CREATE TABLE "User" ("id" TEXT NOT NULL,"email" TEXT NOT NULL,"displayName" TEXT NOT NULL,"passwordHash" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "User_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "User_email_key" ON "User"("email");
CREATE TABLE "Tenant" ("id" TEXT NOT NULL,"name" TEXT NOT NULL,"slug" TEXT NOT NULL,"mode" TEXT NOT NULL DEFAULT 'LIVE',"timezone" TEXT NOT NULL DEFAULT 'Asia/Shanghai',"defaultCurrency" TEXT NOT NULL DEFAULT 'USD',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Tenant_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Tenant_slug_key" ON "Tenant"("slug");
CREATE TABLE "Role" ("id" TEXT NOT NULL,"tenantId" TEXT,"name" TEXT NOT NULL,"permissions" JSONB NOT NULL,"resourceScope" JSONB NOT NULL,"system" BOOLEAN NOT NULL DEFAULT false,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Role_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Role_tenantId_name_key" ON "Role"("tenantId","name");
CREATE TABLE "Membership" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"roleId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Membership_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Membership_userId_tenantId_key" ON "Membership"("userId","tenantId"); CREATE INDEX "Membership_tenantId_status_idx" ON "Membership"("tenantId","status");
CREATE TABLE "Session" ("id" TEXT NOT NULL,"userId" TEXT NOT NULL,"refreshTokenHash" TEXT NOT NULL,"userAgent" TEXT,"ipHash" TEXT,"expiresAt" TIMESTAMP(3) NOT NULL,"revokedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Session_pkey" PRIMARY KEY ("id")); CREATE INDEX "Session_userId_revokedAt_idx" ON "Session"("userId","revokedAt");
CREATE TABLE "LegalEntity" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"name" TEXT NOT NULL,"registeredCountry" TEXT NOT NULL,"registrationNo" TEXT,"status" TEXT NOT NULL DEFAULT 'ACTIVE',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LegalEntity_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "LegalEntity_tenantId_name_key" ON "LegalEntity"("tenantId","name");
CREATE TABLE "SellerAccount" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"legalEntityId" TEXT NOT NULL,"provider" TEXT NOT NULL DEFAULT 'AMAZON_SP_API',"sellerId" TEXT NOT NULL,"logicalRegion" TEXT NOT NULL,"displayName" TEXT NOT NULL,"marketplaceIds" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SellerAccount_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "SellerAccount_provider_sellerId_logicalRegion_key" ON "SellerAccount"("provider","sellerId","logicalRegion"); CREATE INDEX "SellerAccount_tenantId_logicalRegion_idx" ON "SellerAccount"("tenantId","logicalRegion");
CREATE TABLE "PlatformConnection" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"sellerAccountId" TEXT,"provider" TEXT NOT NULL,"state" TEXT NOT NULL DEFAULT 'NOT_CONFIGURED',"externalAccountId" TEXT,"grantedScopes" JSONB NOT NULL,"lastSuccessfulSyncAt" TIMESTAMP(3),"lastHealthCheckedAt" TIMESTAMP(3),"lastErrorCode" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PlatformConnection_pkey" PRIMARY KEY ("id")); CREATE INDEX "PlatformConnection_tenantId_provider_state_idx" ON "PlatformConnection"("tenantId","provider","state");
CREATE TABLE "OAuthState" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"initiatedById" TEXT,"stateHash" TEXT NOT NULL,"redirectUri" TEXT NOT NULL,"expiresAt" TIMESTAMP(3) NOT NULL,"consumedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "OAuthState_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "OAuthState_stateHash_key" ON "OAuthState"("stateHash"); CREATE INDEX "OAuthState_tenantId_expiresAt_consumedAt_idx" ON "OAuthState"("tenantId","expiresAt","consumedAt");
CREATE TABLE "ConnectionHealth" ("id" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"status" TEXT NOT NULL,"checks" JSONB NOT NULL,"requestId" TEXT NOT NULL,"checkedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ConnectionHealth_pkey" PRIMARY KEY ("id")); CREATE INDEX "ConnectionHealth_connectionId_checkedAt_idx" ON "ConnectionHealth"("connectionId","checkedAt");
CREATE TABLE "Order" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"sellerAccountId" TEXT NOT NULL,"amazonOrderId" TEXT NOT NULL,"marketplaceId" TEXT NOT NULL,"purchaseDate" TIMESTAMP(3) NOT NULL,"status" TEXT NOT NULL,"fulfillment" TEXT,"currency" TEXT NOT NULL,"amount" DECIMAL(20,6),"itemCount" INTEGER,"sourceUpdatedAt" TIMESTAMP(3) NOT NULL,"sourceRecordId" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "Order_sellerAccountId_amazonOrderId_key" ON "Order"("sellerAccountId","amazonOrderId"); CREATE INDEX "Order_tenantId_purchaseDate_idx" ON "Order"("tenantId","purchaseDate");
CREATE TABLE "InventorySnapshot" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"sellerAccountId" TEXT NOT NULL,"sku" TEXT NOT NULL,"title" TEXT,"available" INTEGER NOT NULL DEFAULT 0,"inbound" INTEGER NOT NULL DEFAULT 0,"reserved" INTEGER NOT NULL DEFAULT 0,"sourceUpdatedAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "InventorySnapshot_pkey" PRIMARY KEY ("id")); CREATE UNIQUE INDEX "InventorySnapshot_sellerAccountId_sku_key" ON "InventorySnapshot"("sellerAccountId","sku"); CREATE INDEX "InventorySnapshot_tenantId_available_idx" ON "InventorySnapshot"("tenantId","available");
CREATE TABLE "SyncJob" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"connectionId" TEXT NOT NULL,"type" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"progressCurrent" INTEGER NOT NULL DEFAULT 0,"progressTotal" INTEGER NOT NULL DEFAULT 0,"attempts" INTEGER NOT NULL DEFAULT 0,"failureCode" TEXT,"requestId" TEXT NOT NULL,"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SyncJob_pkey" PRIMARY KEY ("id")); CREATE INDEX "SyncJob_tenantId_createdAt_idx" ON "SyncJob"("tenantId","createdAt");
CREATE TABLE "AuditEvent" ("id" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"actorId" TEXT,"action" TEXT NOT NULL,"resourceType" TEXT NOT NULL,"resourceId" TEXT,"requestId" TEXT NOT NULL,"result" TEXT NOT NULL,"detail" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AuditEvent_pkey" PRIMARY KEY ("id")); CREATE INDEX "AuditEvent_tenantId_createdAt_idx" ON "AuditEvent"("tenantId","createdAt");
